head.b:skin:
:root{--bg-color:#ffffff;--text-color:#1a1a1a;--header-bg:#000000;--accent:#0070f3;}
body.dark-mode{--bg-color:#121212;--text-color:#ffffff;}
body{margin:0;font-family:sans-serif;background:var(--bg-color);color:var(--text-color);transition:.3s}
header{background:var(--header-bg);color:#fff;padding:40px 20px;text-align:center;border-bottom:4px solid var(--accent)}
nav{background:#111;padding:12px;display:flex;justify-content:center;gap:15px}
nav a{color:#fff;text-decoration:none;font-weight:bold}
#theme-toggle{background:var(--accent);color:#fff;border:none;padding:6px 12px;border-radius:20px}
main{max-width:900px;margin:20px auto;padding:0 20px}
.post-card{border-left:5px solid var(--accent);padding:20px;background:#fdfdfd;margin-bottom:30px}
body.dark-mode .post-card{background:#1e1e1e}
footer{background:#000;color:#fff;text-align:center;padding:25px 15px}
.post-card a{text-decoration:none;color:#0070f3;font-weight:bold}
